def grav_diag(g, maxsteps=None):
    H,W=len(g),len(g[0])
    g=[row[:] for row in g]
    for step in range(maxsteps or H*W):
        moved=False
        for r in range(H-2,-1,-1):
            for c in range(W-2,-1,-1):
                if g[r][c]!=0 and g[r+1][c+1]==0:
                    g[r+1][c+1]=g[r][c]; g[r][c]=0; moved=True
        if not moved: break
