def solve(g):
    g=np.array(g); H,W=g.shape
    cnt=Counter(int(x) for x in g.flatten())
    bg=max(cnt,key=cnt.get)
    seen=np.zeros_like(g,bool); best=None
    for r in range(H):
        for c in range(W):
            if g[r,c]!=bg and not seen[r,c]:
                col=int(g[r,c]); q=deque([(r,c)]); seen[r,c]=True; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and not seen[a,b] and g[a,b]==col:
                            seen[a,b]=True; q.append((a,b))
                if best is None or len(cells)>len(best): best=cells
    objset=set(best)
    def is_obj(r,c): return (r,c) in objset
    out=g.copy()
    for r in range(H):
        for c in range(W):
            v=int(g[r,c])
            if v==bg or is_obj(r,c): continue
            min_dist=min(abs(r-rr)+abs(c-cc) for rr,cc in [(i,j) for i in range(H) for j in range(W) if is_obj(i,j)])
            bd=99; t=None
            for sr in (-1,1):
                for sc in (-1,1):
                    rr,cc=r+sr,c+sc; d=1
                    while 0<=rr<H and 0<=cc<W and not is_obj(rr,cc):
                        rr+=sr; cc+=sc; d+=1
                    if 0<=rr<H and 0<=cc<W and is_obj(rr,cc) and d<bd:
                        bd=d; t=(rr,cc)
            if t:
                out[t[0],t[1]]=v
    return out.tolist()

